const STY = (bg) => `position:absolute;left:50px;width:840px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border-radius:46px;box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.5);background:${bg};color:#ffffff;font-family:inherit;font-weight:800;line-height:1.1;opacity:0;`;
const B1 = `linear-gradient(180deg,color-mix(in srgb,var(--acc) 72%,#fff),var(--acc) 55%,color-mix(in srgb,var(--acc) 84%,#000))`;
const B2 = `linear-gradient(180deg,color-mix(in srgb,var(--acc2) 72%,#fff),var(--acc2) 55%,color-mix(in srgb,var(--acc2) 84%,#000))`;

root.innerHTML = `
  <div id="c0" style="${STY(B1)}top:80px;height:160px;font-size:54px;">TRANSPARENCY RULES</div>
  <div id="c1" style="${STY(B2)}top:380px;height:160px;font-size:54px;">SUBSEQUENT VIOLATIONS</div>
  <div id="c2" style="${STY(B1)}top:680px;height:320px;">
    <div id="num" style="font-size:110px">$0</div>
    <div style="font-size:44px;opacity:0.8;margin-top:10px">MAXIMUM FINE</div>
  </div>
  <svg style="position:absolute;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:12;stroke-linecap:round;opacity:0.4;">
    <path id="l0" d="M470 240 L470 380" />
    <path id="l1" d="M470 540 L470 680" />
  </svg>
`;

const items = [root.querySelector('#c0'), root.querySelector('#c1'), root.querySelector('#c2')];
const numEl = root.querySelector('#num');
const paths = [root.querySelector('#l0'), root.querySelector('#l1')].map(p => {
  const len = p.getTotalLength();
  p.style.strokeDasharray = len;
  p.style.strokeDashoffset = len;
  return { el: p, len };
});

function frame(t, p, d) {
  const limit = d * 0.55;
  const tf = Math.min(t, limit);

  // Cards timing: 0.0, 0.8, 1.6
  items.forEach((el, i) => {
    const s = spr(tf, i * 0.8, 0.8, 8);
    el.style.opacity = clamp(s * 2);
    el.style.transform = `translateY(${lerp(40, 0, E_OUT(clamp(s)))}px) scale(${lerp(0.9, 1, E_OUT(clamp(s)))})`;
  });

  // Paths timing: 0.5, 1.3
  paths.forEach((pObj, i) => {
    const start = 0.5 + i * 0.8;
    const pProg = E_OUT(clamp((tf - start) / 0.6));
    pObj.el.style.strokeDashoffset = pObj.len * (1 - pProg);
  });

  // Counter timing: starts after 3rd card entrance
  const countProg = E_INOUT(clamp((tf - 1.8) / 1.7));
  const val = Math.floor(lerp(0, 3000000, countProg));
  numEl.textContent = '$' + val.toLocaleString();
}
